css:
.sm{max-width:1120px;margin:0 auto}
.sm h1{margin:0 0 6px;font-size:22px;font-weight:600}
.sm .lead{margin:0 0 20px;font-size:14px;color:#6b7472;max-width:62ch}
.sm .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:20px}
.sm .card{background:#fff;border:1px solid #dfe4e3;border-radius:12px;padding:16px}
.sm .card .num{font-size:28px;font-weight:700;color:#005653;line-height:1.1}
.sm .card .lbl{font-size:12px;color:#77817e;margin-top:4px}
.sm .panel{background:#fff;border:1px solid #dfe4e3;border-radius:12px;padding:18px;margin-bottom:16px}
.sm .panel h2{margin:0 0 10px;font-size:15px;font-weight:600}
.sm .explain{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;font-size:13px;color:#55605d}
.sm .explain b{display:block;color:#1e1e1e;margin-bottom:3px}
.sm .note{background:#fffaf0;border:1px solid #f0d9a8;border-radius:9px;padding:11px 13px;font-size:13px;color:#55605d;margin-top:12px}
.sm .clusters{display:flex;flex-direction:column;gap:6px}
.sm .cl-row{display:grid;grid-template-columns:220px 1fr 50px;align-items:center;gap:10px;font-size:13px}
.sm .cl-bar{display:block;height:10px;border-radius:5px;background:#005653}
.sm .cl-track{display:block;height:10px;background:#eef1f0;border-radius:5px;overflow:hidden}
.sm table.smt{width:100%;border-collapse:collapse;font-size:13px}
.sm table.smt th{text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:#77817e;
 font-weight:600;padding:0 10px 8px 0;border-bottom:1px solid #eceff0;white-space:nowrap}
.sm table.smt td{padding:9px 10px 9px 0;border-top:1px solid #f0f3f2;vertical-align:top}
.sm table.smt td.phrase{font-weight:500;color:#1e1e1e}
.sm table.smt td.muted{color:#a8b0ad}
.sm .pg{display:inline-block;background:#eef3f1;border-radius:5px;padding:1px 6px;margin:1px 3px 1px 0;font-size:11px;color:#36423f}
.sm .nc{color:#a8b0ad;font-style:italic}
.sm .yes{color:#136c2e;font-weight:600}
.sm details.xq summary{cursor:pointer;font-size:13px;color:#005653;font-weight:500}
.sm .xq-list{margin:10px 0 0;padding-left:18px;font-size:13px;line-height:1.9;color:#36423f}
@media(max-width:700px){.sm table.smt{font-size:12px}.sm .cl-row{grid-template-columns:140px 1fr 40px}}
